#!/usr/bin/env node
// The images behind the share cards (Open Graph / Twitter): one of his photos, the BM logo, the words
// set in the site's own fonts (Barlow Condensed and Barlow, turned into paths with opentype.js so no
// system font sneaks in), the numbers, the domain and the tricolour. Two shapes per page: 1200×630
// for most networks, 1200×1200 for the ones that crop to a square (WhatsApp, Mastodon, iMessage).
// Run `npm run cards` after changing the words or the numbers. Nothing here is generated by AI.
import sharp from 'sharp';
import opentype from 'opentype.js';
import { readFile, mkdir } from 'node:fs/promises';

const root = new URL('..', import.meta.url).pathname;
const out = `${root}public/`;
const logoFile = `${root}src/assets/bm-logo.png`;
const BG = '#0b0b0c';
const RED = '#ff2a20';
const YELLOW = '#fdda24';

const font = async (file) => opentype.parse((await readFile(file)).buffer.slice(0));
const display = await font(`${root}node_modules/@fontsource/barlow-condensed/files/barlow-condensed-latin-800-normal.woff`);
const display700 = await font(`${root}node_modules/@fontsource/barlow-condensed/files/barlow-condensed-latin-700-normal.woff`);
const text = await font(`${root}node_modules/@fontsource/barlow/files/barlow-latin-500-normal.woff`);

/** Path data written out in full: opentype's compact toPathData() loses glyphs in librsvg. */
const n = (v) => v.toFixed(2);
const pathData = (path) =>
  path.commands
    .map((c) => {
      switch (c.type) {
        case 'M': return `M${n(c.x)} ${n(c.y)}`;
        case 'L': return `L${n(c.x)} ${n(c.y)}`;
        case 'Q': return `Q${n(c.x1)} ${n(c.y1)} ${n(c.x)} ${n(c.y)}`;
        case 'C': return `C${n(c.x1)} ${n(c.y1)} ${n(c.x2)} ${n(c.y2)} ${n(c.x)} ${n(c.y)}`;
        default: return 'Z';
      }
    })
    .join(' ');

/** Text as SVG paths, one per glyph, with a width check so nothing runs off the card.
 *  No GPOS kerning: opentype.js cuts strings short at some kern pairs in these fonts. */
function word(f, str, x, y, size, { fill = '#fff', tracking = 0, maxWidth = Infinity, anchor = 'start' } = {}) {
  const opts = { letterSpacing: tracking, kerning: false };
  let s = size;
  while (f.getAdvanceWidth(str, s, opts) > maxWidth && s > 10) s -= 1;
  const w = f.getAdvanceWidth(str, s, opts);
  const x0 = anchor === 'end' ? x - w : anchor === 'middle' ? x - w / 2 : x;
  const scale = s / f.unitsPerEm;
  let cx = x0;
  const paths = [];
  for (const g of f.stringToGlyphs(str)) {
    const d = pathData(g.getPath(cx, y, s));
    if (d) paths.push(`<path fill="${fill}" d="${d}"/>`);
    cx += g.advanceWidth * scale + tracking * s;
  }
  return { svg: paths.join(''), width: w, size: s };
}

const cards = {
  home: {
    photo: 'bmw-m1-procar.jpg',
    title: ['BELGIAN', 'MOTORSPORT'],
    tagline: 'PASSIONATE ABOUT CARS',
    sub: 'Motorsport photography and film from Belgium & Europe, since 2006.',
    facts: ['20 YEARS TRACKSIDE', '125K+ SUBSCRIBERS', '62M+ VIEWS', '9,500+ PHOTOS'],
    position: 'centre',
  },
  contact: {
    photo: 'porsche-911-rsr-spa.jpg',
    title: ['WANT TO WORK', 'WITH ME?'],
    tagline: 'BELGIAN MOTORSPORT · BASED IN BELGIUM',
    sub: 'Race weekends, teams and drivers, car portraits, film with real sound.',
    facts: ['BOOKINGS', 'PRINTS', 'LICENSING', 'REPLY BY EMAIL'],
    position: 'right',
  },
  privacy: {
    photo: 'aston-martin-dbr9.jpg',
    title: ['PRIVACY'],
    tagline: 'BELGIAN MOTORSPORT',
    sub: 'No cookies, no trackers. Short, because there’s little to tell.',
    facts: ['NO COOKIES', 'NO ANALYTICS', 'FORM BY EMAIL ONLY'],
    position: 'centre',
  },
};

async function render(name, c, W, H) {
  const square = W === H;
  const pad = 72;
  const pic = await sharp(`${root}src/assets/hero/${c.photo}`).resize(W, H, { fit: 'cover', position: c.position }).toBuffer();
  const logoW = square ? 360 : 300;
  const logo = await sharp(logoFile).resize({ width: logoW }).png().toBuffer();
  const logoH = Math.round((logoW * 512) / 1380);

  // Type sizes by card shape.
  const titleSize = square ? 150 : 116;
  const titleLead = Math.round(titleSize * 0.88);
  const bottom = H - 8; // above the stripe
  const parts = [];
  let y = bottom - 150; // facts row baseline
  // Facts row: small caps in a row, dots between.
  const factsStr = c.facts.join('   ·   ');
  const facts = word(display700, factsStr, pad, y, square ? 30 : 28, { fill: '#cfcac1', tracking: 0.08, maxWidth: W - 2 * pad });
  parts.push(facts.svg);
  // Domain, right-aligned on the same row when it fits beside the facts; else its own line.
  const domain = word(text, 'belgian-motorsport.com', W - pad, y, square ? 30 : 26, { fill: '#8f8a82', anchor: 'end' });
  if (facts.width + domain.width + 60 < W - 2 * pad) parts.push(domain.svg);
  else parts.push(word(text, 'belgian-motorsport.com', pad, y + 44, 26, { fill: '#8f8a82' }).svg), (y += 44);
  // Sub line.
  y = bottom - 150 - (square ? 76 : 66);
  parts.push(word(text, c.sub, pad, y, square ? 36 : 32, { fill: '#e6e2db', maxWidth: W - 2 * pad }).svg);
  // Tagline.
  y -= square ? 70 : 60;
  parts.push(word(display700, c.tagline, pad + 4, y, square ? 40 : 34, { fill: RED, tracking: 0.3, maxWidth: W - 2 * pad }).svg);
  // Title lines, bottom-up.
  y -= square ? 56 : 48;
  for (const line of [...c.title].reverse()) {
    parts.push(word(display, line, pad - 4, y, titleSize, { fill: '#fff', tracking: -0.01, maxWidth: W - 2 * pad }).svg);
    y -= titleLead;
  }

  const overlay = Buffer.from(`<svg width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="g" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0.25" stop-color="#000" stop-opacity="0.08"/>
      <stop offset="0.6" stop-color="#000" stop-opacity="0.55"/>
      <stop offset="1" stop-color="${BG}" stop-opacity="0.96"/>
    </linearGradient>
    <linearGradient id="t" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#000" stop-opacity="0.55"/>
      <stop offset="1" stop-color="#000" stop-opacity="0"/>
    </linearGradient>
  </defs>
  <rect width="${W}" height="${H}" fill="url(#g)"/>
  <rect width="${W}" height="${Math.round(H * 0.3)}" fill="url(#t)"/>
  ${parts.join('\n  ')}
  <rect x="0" y="${H - 8}" width="${W / 3}" height="8" fill="#000"/>
  <rect x="${W / 3}" y="${H - 8}" width="${W / 3}" height="8" fill="${YELLOW}"/>
  <rect x="${(2 * W) / 3}" y="${H - 8}" width="${W / 3}" height="8" fill="#e10600"/>
</svg>`);

  const file = `og-${name}${square ? '-square' : ''}.jpg`;
  await sharp(pic)
    // Logo top-right; the words rise from the bottom-left and never meet it.
    .composite([{ input: overlay, left: 0, top: 0 }, { input: logo, left: W - pad - logoW, top: pad - Math.round(logoH * 0.1) }])
    .jpeg({ quality: 86, mozjpeg: true, chromaSubsampling: '4:4:4' })
    .toFile(out + file);
  console.log(file);
}

await mkdir(out, { recursive: true });
for (const [name, c] of Object.entries(cards)) {
  await render(name, c, 1200, 630);
  await render(name, c, 1200, 1200);
}
